<span class="line"><span style="color:#98C379;">                        &quot;gate_proj&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;up_proj&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;down_proj&quot;</span><span style="color:#ABB2BF;">],</span></span>
